// Format the raw query result rows into a compact JSON payload
// for the AI summarization step. Keeps the prompt small and structured.
const rows = $input.all().map(item => item.json);
return [{ json: { report_data: rows, generated_at: new Date().toISOString() } }];

// Extract the plain-text summary from Claude's response
const content = $input.first().json.content || [];
const text = (Array.isArray(content) ? content.find(c => c.type === 'text')?.text : null) || 'No summary generated.';
return [{ json: { summary_text: text } }];

